// Defines every search feed this workflow polls, each tagged with a rough priority
// tier matching the candidate's location preference: 1 = Delhi NCR, 2 = rest of
// India, 3 = UAE, 4 = Australia. Tier 0 = "let the LLM figure out the location"
// (used for the broad Google Alerts feeds, which aren't location-scoped).
//
// GOOGLE_ALERTS_* values must be replaced with the real RSS feed URLs you get after
// creating the two Google Alerts described in docs/search_queries.md (the Alerts
// "RSS feed" link — not the email digest link).

const GOOGLE_ALERTS_LIFE_INSURANCE_VP = 'REPLACE_WITH_GOOGLE_ALERTS_RSS_URL_1';
const GOOGLE_ALERTS_TRAVEL_BUSINESS_HEAD = 'REPLACE_WITH_GOOGLE_ALERTS_RSS_URL_2';

const feeds = [
  { label: 'Google Alerts — Life Insurance VP (Account Mgmt / Transformation)', feedUrl: GOOGLE_ALERTS_LIFE_INSURANCE_VP, priorityTier: 0 },
  { label: 'Google Alerts — Travel & Hospitality Business Head', feedUrl: GOOGLE_ALERTS_TRAVEL_BUSINESS_HEAD, priorityTier: 0 },

  // Optional Indeed regional RSS feeds — Indeed has changed RSS availability by
  // region over the years, so verify these after import; if one 404s or returns
  // empty, just delete that line (see docs/troubleshooting.md).
  { label: 'Indeed India — VP Account Management, Life Insurance (Delhi NCR)', feedUrl: 'https://www.indeed.co.in/rss?q=%22VP+Account+Management%22+%22Life+Insurance%22&l=Delhi+NCR', priorityTier: 1 },
  { label: 'Indeed India — VP Transformation, Life Insurance (Delhi NCR)', feedUrl: 'https://www.indeed.co.in/rss?q=%22VP+Transformation%22+%22Life+Insurance%22&l=Delhi+NCR', priorityTier: 1 },
  { label: 'Indeed India — Business Head, Travel (Delhi NCR)', feedUrl: 'https://www.indeed.co.in/rss?q=%22Business+Head%22+Travel&l=Delhi+NCR', priorityTier: 1 },
  { label: 'Indeed India — VP, Life Insurance / Transformation (pan-India)', feedUrl: 'https://www.indeed.co.in/rss?q=%22VP%22+%22Life+Insurance%22+Transformation', priorityTier: 2 },
  { label: 'Indeed India — Business Head, Travel/Hospitality (pan-India)', feedUrl: 'https://www.indeed.co.in/rss?q=%22Business+Head%22+%22Travel%22', priorityTier: 2 },
  { label: 'Indeed UAE — VP, Life Insurance', feedUrl: 'https://www.indeed.ae/rss?q=%22VP%22+%22Life+Insurance%22', priorityTier: 3 },
  { label: 'Indeed UAE — Business Head, Travel/Hospitality', feedUrl: 'https://www.indeed.ae/rss?q=%22Business+Head%22+Travel', priorityTier: 3 },
  { label: 'Indeed Australia — VP, Life Insurance', feedUrl: 'https://au.indeed.com/rss?q=%22VP%22+%22Life+Insurance%22', priorityTier: 4 },
  { label: 'Indeed Australia — Business Head, Travel/Hospitality', feedUrl: 'https://au.indeed.com/rss?q=%22Business+Head%22+Travel', priorityTier: 4 },
];

return feeds
  .filter(f => f.feedUrl && !f.feedUrl.startsWith('REPLACE_WITH'))
  .map(f => ({ json: f }));

// Fetches every feed produced by "Build Feed List" and parses RSS 2.0 / Atom
// entries into a flat, normalized list.
//
// This runs as ONE Code node (rather than one RSS Feed Read node per feed, with
// downstream nodes reading back $('Build Feed List').item) because that node
// expands a single input item into many output items, and n8n can't reliably
// resolve a paired-item expression across that 1-to-many boundary. Fetching
// and parsing here keeps every entry attached to the feed it came from.

function decodeEntities(str) {
  return (str || '')
    .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function extractTag(block, tag) {
  const m = block.match(new RegExp(`<${tag}[^>]*>([\\s\\S]*?)<\\/${tag}>`, 'i'));
  return m ? decodeEntities(m[1]) : '';
}

function extractLink(block) {
  // RSS: <link>url</link>. Atom: <link href="url"/>.
  const rss = block.match(/<link[^>]*>([\s\S]*?)<\/link>/i);
  if (rss && rss[1].trim()) return decodeEntities(rss[1]);
  const atom = block.match(/<link[^>]*href=["']([^"']+)["']/i);
  return atom ? atom[1] : '';
}

function parseFeed(xml) {
  const isAtom = /<feed[\s>]/i.test(xml) && !/<rss[\s>]/i.test(xml);
  const tag = isAtom ? 'entry' : 'item';
  const blocks = xml.match(new RegExp(`<${tag}[\\s\\S]*?<\\/${tag}>`, 'gi')) || [];
  return blocks.map(block => ({
    title: extractTag(block, 'title'),
    link: extractLink(block),
    pubDate: extractTag(block, isAtom ? 'published' : 'pubDate') || extractTag(block, 'updated'),
    snippet: (extractTag(block, isAtom ? 'summary' : 'description') || extractTag(block, 'content')).slice(0, 500),
  }));
}

const feeds = $input.all();
const results = [];

for (const feed of feeds) {
  const { label, feedUrl, priorityTier } = feed.json;
  try {
    const xml = await this.helpers.httpRequest({
      url: feedUrl,
      method: 'GET',
      headers: { 'User-Agent': 'Mozilla/5.0 (compatible; job-alert-bot/1.0)' },
      timeout: 15000,
    });
    const entries = parseFeed(typeof xml === 'string' ? xml : String(xml));
    for (const entry of entries) {
      if (!entry.title || !entry.link) continue;
      results.push({ json: { ...entry, sourceLabel: label, priorityTier } });
    }
  } catch (err) {
    // One broken feed (e.g. Indeed RSS disabled in a region) must not fail the run.
    results.push({ json: { fetchError: true, feed: label, error: err.message } });
  }
}

return results;

// Drops feed-fetch error markers, keeps only postings published within the last
// LOOKBACK_HOURS, and skips anything already alerted in a previous run (tracked
// in this workflow's static data, keyed by link).
//
// Static data lives with the workflow on this n8n instance and survives between
// scheduled runs, but resets if you delete and re-import the workflow fresh.

const LOOKBACK_HOURS = 72;
const MAX_SEEN_LINKS = 1000;

const staticData = $getWorkflowStaticData('global');
if (!Array.isArray(staticData.seenLinks)) staticData.seenLinks = [];
const seen = new Set(staticData.seenLinks);

const cutoff = Date.now() - LOOKBACK_HOURS * 60 * 60 * 1000;
const fresh = [];

for (const item of $input.all()) {
  const j = item.json;
  if (j.fetchError) continue;
  if (!j.link || seen.has(j.link)) continue;

  const published = j.pubDate ? Date.parse(j.pubDate) : NaN;
  if (!Number.isNaN(published) && published < cutoff) continue;

  fresh.push(item);
  seen.add(j.link);
}

staticData.seenLinks = Array.from(seen).slice(-MAX_SEEN_LINKS);

return fresh;

// Builds one or more Telegram-ready Markdown digest messages from the relevant,
// classified postings that survived the "Relevant Only" filter. Splits into
// multiple messages if the digest would exceed Telegram's ~4096-character limit.

const TIER_LABELS = {
  1: '🟢 Delhi NCR',
  2: '🟡 India (other)',
  3: '🔵 UAE',
  4: '🟣 Australia',
  5: '⚪ Other (open to Indian profiles)',
};
const MAX_MESSAGE_LENGTH = 3800;

function tierOf(item) {
  const t = item.json.output && item.json.output.location_tier;
  return Number.isInteger(t) ? t : (item.json.priorityTier || 5) || 5;
}

function formatEntry(item) {
  const j = item.json;
  const out = j.output || {};
  const title = j.title || 'Untitled role';
  const loc = out.location_text || 'Location unclear — check listing';
  const reason = out.reason ? `\n_${out.reason}_` : '';
  return `*${title}*\n📍 ${loc} | via ${j.sourceLabel || 'search'}${reason}\n🔗 ${j.link}`;
}

const items = $input.all().slice().sort((a, b) => tierOf(a) - tierOf(b));

const chunks = [];
let current = '🔔 *New role matches found*\n';
let currentTier = null;

for (const item of items) {
  const tier = tierOf(item);
  let addition = '';
  if (tier !== currentTier) {
    addition += `\n\n*${TIER_LABELS[tier] || 'Other'}*\n`;
    currentTier = tier;
  }
  addition += `\n${formatEntry(item)}\n`;

  if ((current + addition).length > MAX_MESSAGE_LENGTH) {
    chunks.push(current);
    current = addition;
  } else {
    current += addition;
  }
}
if (current.trim()) chunks.push(current);

return chunks.map(message => ({ json: { message } }));
